package org.example;

import jakarta.persistence.*;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

@Entity
@Table(name = "hotel")
@Data
@NoArgsConstructor
@AllArgsConstructor
public class Hotel {
    @Id
    @Column(name = "id")
    // NOTE: removed @GeneratedValue because the target SQL Server table does not have
    // IDENTITY on the id column. We will assign ids in the DAO when needed to avoid
    // INSERT failures. If you later make the DB column IDENTITY, you can restore
    // @GeneratedValue(strategy = GenerationType.IDENTITY).
    private Integer id;

    @Column(name = "category")
    String category;

    @Column(name = "name")
    String name;

    @Column(name = "owner")
    String owner;

    @Column(name = "contact")
    String contact;

    @Column(name = "address")
    String address;

    @Column(name = "city")
    String city;

    @Column(name = "citycode")
    String citycode;

    @Column(name = "phone")
    String phone;

    @Column(name = "noRooms")
    int noRooms;

    @Column(name = "noBeds")
    int noBeds;
    // The UI supports an "options" column but the existing DB schema may not have
    // a corresponding column. Make this field transient so the application can
    // keep the UI functionality without requiring a DB schema change.
    @Transient
    String options;

    // Keep existing convenience constructor to avoid changing many call sites.
    public Hotel(Integer id,
                 String category,
                 String name,
                 String owner,
                 String contact,
                 String address,
                 String city,
                 String citycode,
                 String phone,
                 int noRooms,
                 int noBeds) {
        this.id = id;
        this.category = category;
        this.name = name;
        this.owner = owner;
        this.contact = contact;
        this.address = address;
        this.city = city;
        this.citycode = citycode;
        this.phone = phone;
        this.noRooms = noRooms;
        this.noBeds = noBeds;
        this.options = ""; // default empty
    }
}

package org.example;

import jakarta.persistence.*;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

@Entity
@Table(name = "hotel")
@Data
@NoArgsConstructor
@AllArgsConstructor
public class Hotel {
    @Id
    @Column(name = "id")
    // NOTE: removed @GeneratedValue because the target SQL Server table does not have
    // IDENTITY on the id column. We will assign ids in the DAO when needed to avoid
    // INSERT failures. If you later make the DB column IDENTITY, you can restore
    // @GeneratedValue(strategy = GenerationType.IDENTITY).
    private Integer id;

    @Column(name = "category")
    String category;

    @Column(name = "name")
    String name;

    @Column(name = "owner")
    String owner;

    @Column(name = "contact")
    String contact;

    @Column(name = "address")
    String address;

    @Column(name = "city")
    String city;

    @Column(name = "citycode")
    String citycode;

    @Column(name = "phone")
    String phone;

    @Column(name = "noRooms")
    int noRooms;

    @Column(name = "noBeds")
    int noBeds;
    // Persist options to DB. Make sure the `hotel` table has an `options` column
    // (e.g. NVARCHAR(255) NULL). If the DB doesn't have this column yet, run the
    // provided migration SQL before using the UI to save options.
    @Column(name = "options", nullable = true)
    String options;

    // Keep existing convenience constructor to avoid changing many call sites.
    public Hotel(Integer id,
                 String category,
                 String name,
                 String owner,
                 String contact,
                 String address,
                 String city,
                 String citycode,
                 String phone,
                 int noRooms,
                 int noBeds) {
        this.id = id;
        this.category = category;
        this.name = name;
        this.owner = owner;
        this.contact = contact;
        this.address = address;
        this.city = city;
        this.citycode = citycode;
        this.phone = phone;
        this.noRooms = noRooms;
        this.noBeds = noBeds;
        this.options = ""; // default empty
    }
}

package org.example;

import org.hibernate.Session;
import org.hibernate.Transaction;

import java.util.List;

public class HotelDAO {

    public List<Hotel> findAll() {
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.createQuery("from Hotel", Hotel.class).list();
        }
    }

    public Hotel findById(int id) {
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.get(Hotel.class, id);
        }
    }

    public Hotel saveOrUpdate(Hotel hotel) {
        Transaction tx = null;
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            tx = session.beginTransaction();
            // Use persist for new entities (id == null) and merge for existing ones
            if (hotel.getId() == null) {
                session.persist(hotel);
            } else {
                hotel = (Hotel) session.merge(hotel);
            }
            tx.commit();
            // Refresh to get any generated values from DB
            session.refresh(hotel);
            return hotel;
        } catch (Exception e) {
            if (tx != null) {
                try {
                    tx.rollback();
                } catch (Exception rollbackEx) {
                    // Connection might already be closed
                }
            }
            throw e;
        }
    }

    public void deleteById(int id) {
        Transaction tx = null;
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            tx = session.beginTransaction();
            Hotel h = session.get(Hotel.class, id);
            if (h != null) {
                session.remove(h);
            }
            tx.commit();
        } catch (Exception e) {
            if (tx != null) tx.rollback();
            throw e;
        }
    }

}

package org.example;

import org.hibernate.Session;
import org.hibernate.Transaction;

import java.util.List;

public class HotelDAO {

    public List<Hotel> findAll() {
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.createQuery("from Hotel", Hotel.class).list();
        }
    }

    public Hotel findById(int id) {
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            return session.get(Hotel.class, id);
        }
    }

    public Hotel saveOrUpdate(Hotel hotel) {
        Transaction tx = null;
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            tx = session.beginTransaction();
            // Use persist for new entities (id == null) and merge for existing ones
            if (hotel.getId() == null) {
                // The DB table may not use IDENTITY for id. Compute a new id safely here
                // by selecting the current max(id) and incrementing. This is not ideal
                // for high-concurrency environments but works for small desktop apps.
                Integer maxId = session.createQuery("select max(h.id) from Hotel h", Integer.class).uniqueResult();
                int nextId = (maxId == null) ? 1 : (maxId + 1);
                hotel.setId(nextId);
                session.persist(hotel);
            } else {
                hotel = (Hotel) session.merge(hotel);
            }
            tx.commit();
            // Refresh to get any generated values from DB
            session.refresh(hotel);
            return hotel;
        } catch (Exception e) {
            if (tx != null) {
                try {
                    tx.rollback();
                } catch (Exception rollbackEx) {
                    // Connection might already be closed
                }
            }
            throw e;
        }
    }

    public void deleteById(int id) {
        Transaction tx = null;
        try (Session session = HibernateUtil.getSessionFactory().openSession()) {
            tx = session.beginTransaction();
            Hotel h = session.get(Hotel.class, id);
            if (h != null) {
                session.remove(h);
            }
            tx.commit();
        } catch (Exception e) {
            if (tx != null) tx.rollback();
            throw e;
        }
    }

}

package org.ui_master_data;

import org.example.Hotel;
import org.example.Hotelutil;
import org.ui_transactional_data.HotelTableModel_transaction;
import org.ui_transactional_data.MainFrame_transaction;
import org.ui_transactional_data.newOccupanciesWindow;

import javax.swing.*;
import java.awt.*;
import javax.swing.JOptionPane;
import java.util.ArrayList;

public class newHotelwindow extends JFrame {
    public newHotelwindow(HotelTableModel model) {
        super("New Hotel");
        setSize(1000, 200);
        setDefaultCloseOperation(DISPOSE_ON_CLOSE);
        setVisible(true);
        String[] header= {"category","name","owner","contact","address","city","cityCode","phone","noRooms","noBeds","options"};
        JPanel panel = new JPanel(new GridLayout(2, header.length));
        //setLayout(new GridLayout(0,header.length));
        String[] t1= new String[header.length];
        JTextField[] t2= new JTextField[header.length];
        for(String s : header)
        {
            JLabel label = new JLabel(s);
            label.setHorizontalAlignment(JLabel.CENTER);

            panel.add( label);
        }
        for(int i=0;i<header.length;i++){
            JTextField input = new JTextField();
            input.setColumns(1);
            input.setEditable(true);
            t2[i]=input;

            panel.add(input);

        }

        this.add(panel, BorderLayout.CENTER);
        // add a small options chooser and save button in the south
        JPanel southPanel = new JPanel(new FlowLayout(FlowLayout.CENTER));
        JButton chooseOptionsBtn = new JButton("choose options");
        JButton button = new JButton("save");
        southPanel.add(chooseOptionsBtn);
        southPanel.add(button);
        this.add(southPanel, BorderLayout.SOUTH);

        // predefined options - user can choose one or multiple
        String[] predefinedOptions = {"WiFi", "Breakfast", "Parking", "Pool", "Gym"};
        chooseOptionsBtn.addActionListener(ev -> {
            JPanel opts = new JPanel(new GridLayout(predefinedOptions.length,1));
            JCheckBox[] boxes = new JCheckBox[predefinedOptions.length];
            for(int i=0;i<predefinedOptions.length;i++){
                boxes[i] = new JCheckBox(predefinedOptions[i]);
                opts.add(boxes[i]);
            }
            int res = JOptionPane.showConfirmDialog(this, opts, "Select options", JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
            if(res == JOptionPane.OK_OPTION){
                StringBuilder sb = new StringBuilder();
                for(int i=0;i<boxes.length;i++){
                    if(boxes[i].isSelected()){
                        if(sb.length()>0) sb.append(",");
                        sb.append(predefinedOptions[i]);
                    }
                }
                // set the last text input (options) to the selected comma-separated values
                t2[header.length-1].setText(sb.toString());
            }
        });

        button.addActionListener(e -> {
            for(int i=0;i<header.length;i++){
                t1[i]=t2[i].getText();
                // last field 'options' is optional
                if(t1[i].isBlank() && i != header.length-1){
                    JOptionPane.showMessageDialog(this,"Please fill out all fields");
                    return;
                }
                if(t1[i].isBlank()){
                    t1[i] = "";
                }
            }

            // record is ok
            // Validate numeric fields (NoRooms, NoBeds) before creating the Hotel
            int noRooms;
            int noBeds;
            try {
                noRooms = Integer.parseInt(t1[8].trim());
                noBeds = Integer.parseInt(t1[9].trim());
            } catch (NumberFormatException nfe) {
                JOptionPane.showMessageDialog(this, "Please enter valid integer values for 'noRooms' and 'noBeds'", "Invalid input", JOptionPane.ERROR_MESSAGE);
                return;
            }

            // Create hotel without ID - Hibernate will auto-generate it
            Hotel hotel = new Hotel();
            hotel.setCategory(t1[0]);
            hotel.setName(t1[1]);
            hotel.setOwner(t1[2]);
            hotel.setContact(t1[3]);
            hotel.setAddress(t1[4]);
            hotel.setCity(t1[5]);
            hotel.setCitycode(t1[6]);
            hotel.setPhone(t1[7]);
            hotel.setNoRooms(noRooms);
            hotel.setNoBeds(noBeds);
            hotel.setOptions(t1[10]);
            model.addHotel(hotel);
            // The DAO may return a different managed instance when saving. Retrieve
            // the newly added hotel's id from the model to be safe.
            int newId = model.getHotel(model.getRowCount() - 1).getId(); // Get the auto-generated ID
            int response = JOptionPane.showConfirmDialog(
                    this,
                    "Would you like to add occupancies?",
                    "Create occupancies",
                    JOptionPane.YES_NO_OPTION
            );
            if(response == JOptionPane.YES_OPTION){
                    try {
                        MainFrame_transaction mftrans= new MainFrame_transaction();
                        mftrans.setVisible(true);
                        HotelTableModel_transaction trmodel= mftrans.getModel();
                        new newOccupanciesWindow(newId, trmodel).setVisible(true);
                    } catch (RuntimeException ex) {
                        JOptionPane.showMessageDialog(null, "Failed to open transactional frame: " + ex.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
                        throw ex;
                    }


            }
            else {
                new popup().setVisible(true);
            }





        });




    }



}

